scenes.css:
#rf-root,.hf-root{--x3:#3a3a52;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-zoomout 0.5s cubic-bezier(.7,0,.84,0) 8.5s both;}.cam{position:absolute;inset:0;animation:st-cam 9s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.pc{position:absolute;left:80px;right:80px;top:260px;bottom:360px;display:flex;flex-direction:column;align-items:center;text-align:center}
.pc-av{position:relative;width:300px;height:300px;border-radius:50%;background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent);display:flex;align-items:center;justify-content:center;font-size:110px;font-weight:500;color:var(--rf-text)}
.pc-show{display:flex;align-items:center;gap:14px;margin-top:56px;font:500 32px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-accent)}
.pc-ep{margin-top:18px;font-size:48px;font-weight:600;color:var(--rf-muted)}
.pc-wave{display:flex;align-items:center;gap:7px;height:160px;width:100%;margin:46px 0}
.pc-wave i{flex:1;border-radius:6px;background:var(--rf-accent);animation:pw .9s ease-in-out infinite alternate both}
@keyframes pw{from{transform:scaleY(.25)}to{transform:scaleY(1)}}
.pc-cap{font-size:76px;line-height:1.1;font-weight:600;letter-spacing:-.025em}
.pc-cap span{color:color-mix(in srgb,var(--rf-text) 28%,transparent);animation:cw .25s ease-out both}
@keyframes cw{to{color:var(--rf-text)}}
.pc-host{margin-top:auto;font:500 28px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}

#rf-root,.hf-root{--x3:#3a3a52;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-zoomin 0.7s cubic-bezier(.16,1,.3,1) both;}.cam{position:absolute;inset:0;animation:st-cam 5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.lt{display:inline-block;animation:lt-pop 0.6s cubic-bezier(.16,1,.3,1) both}
@keyframes lt-pop{from{opacity:0;transform:translateY(.35em)}to{opacity:1;transform:none}}.acc{color:var(--rf-accent);font-style:normal}.ctr{align-items:center;text-align:center}
.mark .bm{width:260px;height:260px}.mark{animation:mk-in 1s cubic-bezier(.16,1,.3,1) 0.35s both}
@keyframes mk-in{from{transform:scale(.8);opacity:0}}
.bn{margin-top:60px;font-size:140px;font-weight:600;letter-spacing:-.05em;line-height:1}
.ln{margin:30px 0 0;font-size:50px;font-weight:600;color:var(--rf-muted);max-width:840px;line-height:1.25}
.btn{margin-top:70px;font-size:46px;font-weight:600;padding:34px 70px;border-radius:999px;background:var(--rf-text);color:var(--rf-bg);animation:k-pop .7s cubic-bezier(.16,1,.3,1) 1.45s both}
.url{margin-top:40px;font:600 36px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
